// ============================================
// LEAD SCORING ENGINE
// ============================================
function formatDate(input) {
  const d = new Date(input);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const day   = String(d.getDate()).padStart(2, '0');
  const month = months[d.getMonth()];
  const year  = d.getFullYear();
  const hours = String(d.getHours()).padStart(2, '0');
  const mins  = String(d.getMinutes()).padStart(2, '0');
  return `${day} ${month} ${year} - ${hours}:${mins}`;
}

const data = $input.first().json.body;

let score = 0;
const breakdown = {};

// --- 1. BUDGET SCORE (max 30 pts) ---
const budget = parseInt(data.budget) || 0;
if (budget >= 20000)      { score += 30; breakdown.budget = 30; }
else if (budget >= 10000) { score += 22; breakdown.budget = 22; }
else if (budget >= 5000)  { score += 15; breakdown.budget = 15; }
else if (budget >= 1000)  { score += 8;  breakdown.budget = 8;  }
else                      { score += 3;  breakdown.budget = 3;  }

// --- 2. TIMELINE SCORE (max 30 pts) ---
const timeline = data.timeline || '';
if (timeline === 'immediate')  { score += 30; breakdown.timeline = 30; }
else if (timeline === '1-3months') { score += 18; breakdown.timeline = 18; }
else                           { score += 5;  breakdown.timeline = 5;  }

// --- 3. COMPANY SIZE SCORE (max 25 pts) ---
const size = data.companySize || '';
if (size === '500+')       { score += 25; breakdown.companySize = 25; }
else if (size === '201-500') { score += 20; breakdown.companySize = 20; }
else if (size === '51-200') { score += 14; breakdown.companySize = 14; }
else if (size === '11-50')  { score += 8;  breakdown.companySize = 8;  }
else                        { score += 3;  breakdown.companySize = 3;  }

// --- 4. ENGAGEMENT SCORE (max 15 pts) ---
const needsLen = (data.needs || '').trim().length;
if (needsLen > 150)      { score += 15; breakdown.engagement = 15; }
else if (needsLen > 80)  { score += 10; breakdown.engagement = 10; }
else if (needsLen > 30)  { score += 6;  breakdown.engagement = 6;  }
else                     { score += 2;  breakdown.engagement = 2;  }

// Cap at 100
score = Math.min(score, 100);

// --- CATEGORY ---
let category, priority;
if (score >= 75) {
  category = 'Hot';
  priority = 'HIGH';
} else if (score >= 50) {
  category = 'Warm';
  priority = 'MEDIUM';
} else {
  category = 'Cold';
  priority = 'LOW';
}

return [{
  json: {
    // Original form data
    ...data,
    fullName: `${data.firstName} ${data.lastName}`,
    // Scoring results
    leadScore: score,
    leadCategory: category,
    priority: priority,
    scoreBreakdown: JSON.stringify(breakdown),
    // Meta
    submittedAt: formatDate(data.submittedAt || new Date()),
    processedAt: formatDate(new Date()),
  }
}];

const email = $input.first().json;

const fromRaw = email.from || email.From || '';
const senderEmail = fromRaw.includes('<')
  ? fromRaw.split('<')[1].split('>')[0].trim()
  : fromRaw.trim();

const ourEmail = 'mehedi0017.fireai@gmail.com';
if (senderEmail.toLowerCase() === ourEmail.toLowerCase()) return [];

const labels = email.labels || [];
const isInbox = labels.some(l =>
  (l.id || '').toString().toUpperCase().includes('INBOX') ||
  (l.name || '').toString().toUpperCase().includes('INBOX')
);
if (!isInbox) return [];

return [{
  json: {
    threadId:    email.threadId || '',
    senderEmail: senderEmail,
    senderName:  fromRaw.split('<')[0].trim(),
    snippet:     email.snippet || '',
    subject:     email.subject || email.Subject || '',
    messageId:   email.id || '',
  }
}];

const emailData = $('Extract Email Data').first().json;

// Case 1: Thread ID match
let leadData = null;
try {
  const threadMatch = $('Lookup by Thread ID').first().json;
  if (threadMatch && threadMatch['Email']) {
    leadData = { ...threadMatch, matchType: 'threadId' };
  }
} catch(e) {}

// Case 2: Email match (client replied from new email)
if (!leadData) {
  try {
    const emailMatch = $('Lookup by Email').first().json;
    if (emailMatch && emailMatch['Email']) {
      leadData = { ...emailMatch, matchType: 'email' };
    }
  } catch(e) {}
}

// Case 3: No match — ignore
if (!leadData) return [];

return [{
  json: {
    firstName:   leadData['First Name'] || '',
    lastName:    leadData['Last Name'] || '',
    email:       leadData['Email'] || '',
    company:     leadData['Company'] || '',
    industry:    leadData['Industry'] || '',
    companySize: leadData['Company Size'] || '',
    needs:       leadData['Needs'] || '',
    leadScore:   leadData['Lead Score'] || '',
    category:    leadData['Category'] || 'Cold',
    matchType:   leadData.matchType,
    threadId:    emailData.threadId,
    senderEmail: emailData.senderEmail,
    senderName:  emailData.senderName,
    snippet:     emailData.snippet,
    subject:     emailData.subject,
  }
}];

const d = $input.first().json;

const toneMap = {
  Hot:  'urgent, enthusiastic and action-oriented. This is a HIGH priority lead. Push strongly for an immediate call this week. Be warm but decisive and confident.',
  Warm: 'friendly, helpful and curious. This is a promising lead. Suggest a 20-minute discovery call and ask a follow-up question about their needs.',
  Cold: 'polite, informative and nurturing. This lead needs more time. Be helpful, offer value, and suggest a low-commitment next step.',
};
const tone = toneMap[d.category] || toneMap.Cold;

const systemPrompt = `You are a professional sales representative for Fire AI, a company that builds custom AI Agents for businesses.
Your job is to reply to leads who have responded to your outreach email.
Always write in a natural, human tone — never robotic or overly formal.
Keep replies concise (max 120 words). Sign off as "Fire AI Team".
Never mention AI or automation in your reply.`;

const chatInput = `Write a reply email to this lead.

LEAD CONTEXT:
- Name: ${d.firstName} ${d.lastName}
- Company: ${d.company}
- Industry: ${d.industry}
- Company Size: ${d.companySize}
- Their original need: "${d.needs}"
- Lead Score: ${d.leadScore}/100
- Lead Category: ${d.category}
- How we matched them: ${d.matchType === 'threadId' ? 'They replied to our original email (same thread)' : 'They emailed us from a different email but are in our leads list'}

THEIR LATEST MESSAGE:
"${d.snippet}"

INSTRUCTIONS:
- Tone: ${tone}
- Reference their actual message naturally
- Do NOT include a subject line — only write the email body
- End with a clear call-to-action
- Sign off as: Fire AI Team`;

return [{
  json: {
    systemPrompt,
    chatInput,
    threadId:    d.threadId,
    toEmail:     d.senderEmail,
    replySubject: `Re: ${d.subject}`,
    category:    d.category,
    firstName:   d.firstName,
    email:       d.email,
  }
}];

const aiResponse = $input.first().json;
const prevData = $('Prepare AI Prompt').first().json;

// Extract reply text from OpenAI response
const replyBody = aiResponse.choices?.[0]?.message?.content
  || 'Thank you for your reply. We will get back to you shortly.\n\nBest regards,\nFire AI Team';

return [{
  json: {
    threadId:     prevData.threadId,
    toEmail:      prevData.toEmail,
    replySubject: prevData.replySubject,
    replyBody:    replyBody.trim(),
    category:     prevData.category,
    firstName:    prevData.firstName,
    email:        prevData.email,
  }
}];
